WITH p AS (SELECT %s::date dfrom,%s::date dto,coalesce(%s::text,'') ma_vt,coalesce(%s::text,'') ma_kh,coalesce(%s::text,'') nguon,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR(coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid),x AS (SELECT a.nguon_du_lieu,a.loai_du_lieu,a.ma_kh,a.ma_vt,a.ngay_giao_hang,a.ngay_tinh_toan,a.so_luong,lag(a.so_luong) OVER(PARTITION BY a.nguon_du_lieu,a.loai_du_lieu,a.ma_kh,a.ma_vt,a.ngay_giao_hang ORDER BY a.ngay_tinh_toan) so_luong_truoc FROM public.mfkhsx_po_fc a CROSS JOIN s WHERE s.ok IS NOT NULL AND(s.unrestricted OR s.bs='') AND a.ngay_tinh_toan BETWEEN s.dfrom AND s.dto AND(s.ma_vt='' OR a.ma_vt=ANY(string_to_array(s.ma_vt,',')))AND(s.ma_kh='' OR a.ma_kh=ANY(string_to_array(s.ma_kh,',')))AND(s.nguon='' OR a.nguon_du_lieu=ANY(string_to_array(s.nguon,',')))) SELECT x.*,coalesce(x.so_luong,0)-coalesce(x.so_luong_truoc,0) chenh_lech,count(*) OVER() total FROM x ORDER BY ma_vt,ma_kh,ngay_giao_hang,ngay_tinh_toan LIMIT(SELECT lim FROM p);
